// PayPal REST access (sandbox only).
//
// Orders and Payments go through @paypal/paypal-server-sdk, PayPal's server SDK
// generated by APIMatic. The SDK has no Payouts or webhook-verification
// endpoints, so those two use paypalFetch() below. Both paths share one OAuth
// token cache.

import {
  ApiError,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  type OAuthToken,
} from "@paypal/paypal-server-sdk";
import { paypalConfig } from "../config";

const TIMEOUT_MS = 15_000;
// Refresh a little early so a token never expires mid-request.
const EXPIRY_MARGIN_MS = 60_000;

export class PayPalError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    /** PayPal's error name, e.g. UNPROCESSABLE_ENTITY. */
    public readonly name: string,
    /** details[0].issue, e.g. INSTRUMENT_DECLINED. */
    public readonly issue: string | null,
    public readonly debugId: string | null,
  ) {
    super(message);
  }
}

interface PayPalErrorBody {
  name?: string;
  message?: string;
  debug_id?: string;
  details?: { issue?: string; description?: string }[];
  // OAuth endpoint errors use a different shape.
  error?: string;
  error_description?: string;
}

function fromBody(status: number, body: PayPalErrorBody | undefined, fallback: string): PayPalError {
  const detail = body?.details?.[0];
  const message = detail?.description ?? body?.message ?? body?.error_description ?? fallback;
  return new PayPalError(message, status, body?.name ?? body?.error ?? `HTTP_${status}`, detail?.issue ?? null, body?.debug_id ?? null);
}

function parseBody(text: string): PayPalErrorBody | undefined {
  try {
    return JSON.parse(text) as PayPalErrorBody;
  } catch {
    return undefined;
  }
}

/** Normalize anything thrown by the SDK or fetch into a PayPalError. */
export function toPayPalError(err: unknown): PayPalError {
  if (err instanceof ApiError) {
    const body = (err.result as PayPalErrorBody | undefined) ?? (typeof err.body === "string" ? parseBody(err.body) : undefined);
    return fromBody(err.statusCode, body, err.message);
  }
  // Network failure, timeout or a token that could not be fetched. The SDK keeps
  // a failed token promise for the life of the client, so start a fresh one.
  sdk = null;
  if (err instanceof PayPalError) return err;
  const message = err instanceof Error ? err.message : String(err);
  return new PayPalError(`Could not reach PayPal: ${message}`, 503, "NETWORK_ERROR", null, null);
}

// ---------- OAuth ----------

let token: { value: string; expiresAt: number } | null = null;
let pending: Promise<{ value: string; expiresAt: number }> | null = null;

async function fetchToken(): Promise<{ value: string; expiresAt: number }> {
  const { clientId, clientSecret, apiBase } = paypalConfig();
  if (!clientId || !clientSecret) throw new PayPalError("PayPal credentials are not configured.", 500, "NOT_CONFIGURED", null, null);
  const res = await fetch(`${apiBase}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  const text = await res.text();
  if (!res.ok) throw fromBody(res.status, parseBody(text), "PayPal rejected the client credentials.");
  const body = JSON.parse(text) as { access_token: string; expires_in: number };
  return { value: body.access_token, expiresAt: Date.now() + body.expires_in * 1000 };
}

async function cachedToken(): Promise<{ value: string; expiresAt: number }> {
  if (token && token.expiresAt - EXPIRY_MARGIN_MS > Date.now()) return token;
  // Concurrent callers share one in-flight request.
  pending ??= fetchToken()
    .then((t) => (token = t))
    .finally(() => {
      pending = null;
    });
  return pending;
}

export async function getAccessToken(): Promise<string> {
  return (await cachedToken()).value;
}

// ---------- SDK client ----------

interface Sdk {
  client: Client;
  orders: OrdersController;
  payments: PaymentsController;
}

let sdk: Sdk | null = null;

function toSdkToken(t: { value: string; expiresAt: number }): OAuthToken {
  return {
    accessToken: t.value,
    tokenType: "Bearer",
    // The SDK compares expiry (epoch seconds) against its clock skew to decide when to ask again.
    expiry: BigInt(Math.floor((t.expiresAt - EXPIRY_MARGIN_MS) / 1000)),
  };
}

export function paypal(): Sdk {
  if (sdk) return sdk;
  const { clientId, clientSecret } = paypalConfig();
  const client = new Client({
    environment: Environment.Sandbox,
    timeout: TIMEOUT_MS,
    clientCredentialsAuthCredentials: {
      oAuthClientId: clientId,
      oAuthClientSecret: clientSecret,
      oAuthTokenProvider: async () => toSdkToken(await cachedToken()),
    },
    // GETs are safe to retry; POSTs rely on PayPal-Request-Id instead.
    httpClientOptions: { timeout: TIMEOUT_MS, retryConfig: { maxNumberOfRetries: 2 } },
    // No `logging` key: the SDK then uses its null logger, so request bodies and tokens never reach stdout.
  });
  sdk = { client, orders: new OrdersController(client), payments: new PaymentsController(client) };
  return sdk;
}

// ---------- plain REST for endpoints the SDK lacks ----------

export async function paypalFetch<T>(path: string, init: { method?: string; body?: unknown; rawBody?: string; headers?: Record<string, string> } = {}): Promise<T> {
  const { apiBase } = paypalConfig();
  let res: Response;
  try {
    res = await fetch(`${apiBase}${path}`, {
      method: init.method ?? (init.body !== undefined || init.rawBody !== undefined ? "POST" : "GET"),
      headers: {
        Authorization: `Bearer ${await getAccessToken()}`,
        "Content-Type": "application/json",
        Accept: "application/json",
        ...init.headers,
      },
      body: init.rawBody ?? (init.body === undefined ? undefined : JSON.stringify(init.body)),
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (err) {
    throw toPayPalError(err);
  }
  const text = await res.text();
  if (res.status === 401) token = null;
  if (!res.ok) throw fromBody(res.status, parseBody(text), `PayPal returned HTTP ${res.status}.`);
  return (text ? JSON.parse(text) : {}) as T;
}
